import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BCectEOt.js";const f=JSON.parse('{"title":"關於蒼藍星圖鑑","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hant/others/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hant/others/"}],["meta",{"property":"og:title","content":"關於蒼藍星圖鑑 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Monster Hunter reference data and armor builds for Wilds, Rise with Sunbreak, and World with Iceborne."}]]},"headers":[],"relativePath":"zh-hant/others/index.md","filePath":"zh-hant/others/index.md"}'),n={name:"zh-hant/others/index.md"};function h(i,e,l,s,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="關於蒼藍星圖鑑" tabindex="-1">關於蒼藍星圖鑑 <a class="header-anchor" href="#關於蒼藍星圖鑑" aria-label="Permalink to &quot;關於蒼藍星圖鑑&quot;">​</a></h1><h2 id="應用程式介紹" tabindex="-1">應用程式介紹 <a class="header-anchor" href="#應用程式介紹" aria-label="Permalink to &quot;應用程式介紹&quot;">​</a></h2><p>蒼藍星圖鑑（Sapphire Star Codex）是一款為魔物獵人玩家提供資料查詢與配裝搜尋的應用程式，由 <a href="https://eurekaffeine.github.io/pocket-gallery/" target="_blank" rel="noreferrer">Pocket Gallery</a> 的開發者獨立製作。專案以非商業方式營運，不含廣告，也不設付費功能。</p><h2 id="意見回饋與協作" tabindex="-1">意見回饋與協作 <a class="header-anchor" href="#意見回饋與協作" aria-label="Permalink to &quot;意見回饋與協作&quot;">​</a></h2><p>歡迎協助核對遊戲資料、完善翻譯，或向其他玩家分享本網站。</p><p>應用程式上架時將提供公開回饋管道。回報資料問題時，請註明遊戲與擴充內容、魔物或裝備名稱、使用語言及具體問題，並附上可查證的來源或重現步驟。提交截圖前，請遮蔽個人資訊。</p><p>開發者資訊與後續聯絡方式可透過<a href="https://github.com/eurekaffeine" target="_blank" rel="noreferrer">開發者個人頁面</a>了解。本網站目前不透過表單收集回饋。</p><h2 id="資料來源" tabindex="-1">資料來源 <a class="header-anchor" href="#資料來源" aria-label="Permalink to &quot;資料來源&quot;">​</a></h2><p>資料依遊戲分別擷取與整理，來源包括 <a href="https://docs.wilds.mhdb.io/" target="_blank" rel="noreferrer">MHDB Wilds</a>、<a href="https://mhw-db.com/" target="_blank" rel="noreferrer">MHW DB</a> 與遊戲檔案，並參考社群資料交叉核對。部分內容可能有缺漏或錯誤，將持續補充與修正。</p><h2 id="版權與聲明" tabindex="-1">版權與聲明 <a class="header-anchor" href="#版權與聲明" aria-label="Permalink to &quot;版權與聲明&quot;">​</a></h2><p>蒼藍星圖鑑由遊戲愛好者獨立開發，以非商業方式營運，與 CAPCOM 無關聯，亦未獲其認可或支援。Monster Hunter 的名稱、設計、官方圖示與遊戲資料歸 CAPCOM Co., Ltd. 所有。如權利人要求移除相關內容，專案將配合處理。</p><p>網站以 Pocket Gallery 採用 MIT 授權的 VitePress 元件為基礎改編。該授權僅適用於程式碼，不涵蓋遊戲美術與資料。</p>',12)])])}const u=a(n,[["render",h]]);export{f as __pageData,u as default};
